mapper.select:
SELECT b.bbsinfo_id::TEXT AS row_id, b.bbsinfo_nm, b.bbsinfo_cd, c.code_nm AS bbsinfo_cd_nm, b.bbsinfo_desc, b.list_cnt, b.file_yn, b.file_cnt, b.file_size, b.notice_yn, b.new_cnt, b.use_yn FROM t_bbsinfo b LEFT JOIN t_code c ON c.code_id = b.bbsinfo_cd AND c.p_code_id = 'BBSINFO000' WHERE b.use_yn = 'Y'
AND b.bbsinfo_nm LIKE '%' || #{filterKeyword} || '%'
ORDER BY b.bbsinfo_id DESC LIMIT #{pageSize} OFFSET #{offset}
